pub fn ext_key(ext: &str) -> &'static str {
    match ext {
        "py" | "pyw" | "pyi" | "ipynb" => "python",
        "html" | "htm" => "html",
        "css" | "less" => "css",
        "scss" | "sass" => "scss",
        "js" | "mjs" | "cjs" => "javascript",
        "jsx" | "tsx" => "jsx",
        "ts" | "mts" | "cts" => "typescript",
        "json" | "jsonc" => "json",
        "md" | "markdown" => "markdown",
        "png" | "jpg" | "jpeg" | "gif" | "webp" | "ico" | "bmp" | "avif" => "image",
        "svg" => "svg",
        "sh" | "bash" | "bat" | "cmd" => "shell",
        "ps1" => "powershell",
        "txt" | "log" => "text",
        "csv" | "tsv" => "csv",
        "toml" | "ini" | "cfg" | "yml" | "yaml" | "env" | "gitignore" | "lock" => "config",
        "c" | "h" => "c",
        "cpp" | "hpp" | "cc" => "cpp",
        "cs" => "csharp",
        "java" => "java",
        "go" => "go",
        "rs" => "rust",
        "rb" => "ruby",
        "php" => "php",
        "lua" => "lua",
        "pl" | "pm" => "perl",
        "git" => "git",
        "zig" => "zig",
        "r" => "r",
        "jl" => "julia",
        _ => "file",
    }
}

